  logic [31:0] v;
  initial begin
    repeat (4) @(posedge clk);
    @(negedge clk); aresetn = 1'b1;
    repeat (2) @(posedge clk);
    axr(CSR_ID, v);
    if ((v & 32'hFFFF_F000) !== SCOPE_ID_MAGIC) fail($sformatf("ID magic %h", v));
